/**
 * Writes the launcher icon and splash, drawn from one shape list
 * (scripts/lib/iconart.ts):
 *   - Android: vector drawables (committed).
 *   - iOS: PNGs (Apple requires bitmaps). They are build outputs, gitignored,
 *     and regenerated by `npm run ios`.
 *   The web app's icons are emitted by the Vite build (vite.config.ts).
 *   npx tsx scripts/icon.ts
 */
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { BG, fg, png, raster, squareIcon, type Shape } from './lib/iconart';

// ---------------------------------------------------------------- Android

const res = join(import.meta.dirname, '../android/app/src/main/res');
const rr = ({ x, y, w, h, r }: Shape) =>
  `M${x + r},${y} h${w - 2 * r} a${r},${r} 0 0 1 ${r},${r} v${h - 2 * r} a${r},${r} 0 0 1 -${r},${r} h-${w - 2 * r} a${r},${r} 0 0 1 -${r},-${r} v-${h - 2 * r} a${r},${r} 0 0 1 ${r},-${r} z`;
const path = (s: Shape) => `    <path android:fillColor="${s.fill}" android:pathData="${rr(s)}"/>`;
const fgXml = fg.map(path).join('\n');

const vector = (body: string, size = 108) => `<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="${size}dp" android:height="${size}dp"
    android:viewportWidth="108" android:viewportHeight="108">
${body}
</vector>
`;

// remove bitmap defaults
for (const d of ['hdpi', 'mdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi']) {
  rmSync(join(res, `mipmap-${d}`), { recursive: true, force: true });
  rmSync(join(res, `drawable-land-${d}`), { recursive: true, force: true });
  rmSync(join(res, `drawable-port-${d}`), { recursive: true, force: true });
}
rmSync(join(res, 'drawable/splash.png'), { force: true });
rmSync(join(res, 'drawable-v24'), { recursive: true, force: true });

mkdirSync(join(res, 'drawable'), { recursive: true });
writeFileSync(join(res, 'drawable/ic_launcher_foreground.xml'), vector(fgXml));
writeFileSync(
  join(res, 'drawable/ic_launcher_background.xml'),
  vector(`    <path android:fillColor="${BG}" android:pathData="M0,0h108v108h-108z"/>`),
);
writeFileSync(join(res, 'values/ic_launcher_background.xml'), `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="ic_launcher_background">${BG}</color>
</resources>
`);
const adaptive = `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@drawable/ic_launcher_background"/>
    <foreground android:drawable="@drawable/ic_launcher_foreground"/>
</adaptive-icon>
`;
mkdirSync(join(res, 'mipmap-anydpi-v26'), { recursive: true });
writeFileSync(join(res, 'mipmap-anydpi-v26/ic_launcher.xml'), adaptive);
writeFileSync(join(res, 'mipmap-anydpi-v26/ic_launcher_round.xml'), adaptive);
// pre-26 fallback: a plain vector (background + foreground)
mkdirSync(join(res, 'mipmap-anydpi'), { recursive: true });
const legacy = vector(path({ x: 4, y: 4, w: 100, h: 100, r: 22, fill: BG }) + '\n' + fgXml, 48);
writeFileSync(join(res, 'mipmap-anydpi/ic_launcher.xml'), legacy);
writeFileSync(join(res, 'mipmap-anydpi/ic_launcher_round.xml'), legacy);
// splash: flat background with the icon in the middle
writeFileSync(join(res, 'drawable/splash_logo.xml'), vector(fgXml, 160));
writeFileSync(join(res, 'drawable/splash.xml'), `<?xml version="1.0" encoding="utf-8"?>
<layer-list xmlns:android="http://schemas.android.com/apk/res/android">
    <item><color android:color="${BG}"/></item>
    <item android:drawable="@drawable/splash_logo" android:gravity="center"/>
</layer-list>
`);

const assets = join(import.meta.dirname, '../ios/App/App/Assets.xcassets');
// App icon: opaque square (iOS applies its own mask); the board fills ~72%.
const ICON = 1024;
writeFileSync(join(assets, 'AppIcon.appiconset/AppIcon-1024.png'), squareIcon(ICON));
// Launch logo: same framing as Android's 160dp splash_logo, transparent, @3x.
const LOGO = 480;
writeFileSync(join(assets, 'Splash.imageset/splash-logo@3x.png'), png(raster(fg, LOGO, LOGO / 108, 54), LOGO, false));

console.log('icon + splash written (Android vectors, iOS PNGs)');
